#include <vector>
#include <omp.h>
#include <algorithm>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int P = omp_get_max_threads();
    if (P > n) P = n;
    if (P <= 1) {
        int sum = 0;
        for (int i = 0; i < n; ++i) {
            sum += x[n - 1 - i];
            output[i] = sum;
        }
        return;
    }

    std::vector<int> chunkSums(P, 0);

    #pragma omp parallel num_threads(P)
    {
        const int tid = omp_get_thread_num();

        // Split indices i=0..n-1 into contiguous chunks.
        const int base = n / P;
        const int rem  = n % P;
        const int start = tid * base + std::min(tid, rem);
        const int len   = base + (tid < rem ? 1 : 0);
        const int end   = start + len; // exclusive

        // Local reverse-prefix on this chunk in terms of i, using x[n-1-i].
        int localSum = 0;
        for (int i = start; i < end; ++i) {
            localSum += x[n - 1 - i];
            output[i] = localSum;
        }

        // Each thread writes its own chunk total (no races).
        chunkSums[tid] = localSum;

        #pragma omp barrier

        // Compute offset = sum of chunk totals for all chunks with lower tid.
        // Do it redundantly per thread (P is usually small); avoids races.
        int offset = 0;
        for (int t = 0; t < tid; ++t) offset += chunkSums[t];

        // Add offset to all outputs in this chunk.
        for (int i = start; i < end; ++i) {
            output[i] += offset;
        }
    }
}
